-- Pro Trading reference PostgreSQL schema, DESIGN DRAFT ONLY.
-- Implement via reviewed Alembic migrations; not production-ready DDL.
-- UUIDs, timestamptz, NUMERIC for monetary/measurement correctness.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Toronto');
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, UNIQUE(company_id,name));
CREATE TABLE employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), email text NOT NULL, password_hash text, active boolean NOT NULL DEFAULT true, mfa_required boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,email));
CREATE TABLE permissions (code text PRIMARY KEY);
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), code text NOT NULL, UNIQUE(company_id,code));
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id), permission_code text REFERENCES permissions(code), PRIMARY KEY(role_id,permission_code));
CREATE TABLE employee_roles (employee_id uuid REFERENCES employees(id), role_id uuid REFERENCES roles(id), PRIMARY KEY(employee_id,role_id));
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), external_ref text, name text NOT NULL, email text, phone text, address_json jsonb NOT NULL DEFAULT '{}'::jsonb, payment_terms_days integer NOT NULL DEFAULT 0 CHECK(payment_terms_days>=0), active boolean NOT NULL DEFAULT true, UNIQUE(company_id,external_ref));
CREATE TABLE vendors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), external_ref text, name text NOT NULL, country_code text, email text, active boolean NOT NULL DEFAULT true, UNIQUE(company_id,external_ref));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), sku text NOT NULL, name text NOT NULL, category text, active boolean NOT NULL DEFAULT true, stock_unit text NOT NULL CHECK(stock_unit IN ('BOX','PIECE','LB','KG')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,sku));
CREATE TABLE product_aliases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), vendor_id uuid REFERENCES vendors(id), alias text NOT NULL);
CREATE TABLE product_unit_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), unit_code text NOT NULL CHECK(unit_code IN('BOX','PIECE','LB','KG')), case_count numeric(18,4), case_weight_lb numeric(18,4), is_default boolean NOT NULL DEFAULT false, CHECK(case_count IS NULL OR case_count>0), CHECK(case_weight_lb IS NULL OR case_weight_lb>0));
CREATE TABLE price_book_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), version_code text NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','ACTIVE','ARCHIVED')), effective_at timestamptz, approved_by uuid REFERENCES employees(id), source_hash text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,version_code));
CREATE TABLE price_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES price_book_versions(id), product_id uuid NOT NULL REFERENCES products(id), customer_id uuid REFERENCES customers(id), customer_group text, unit_code text NOT NULL CHECK(unit_code IN('BOX','PIECE','LB','KG')), rate numeric(18,4) NOT NULL CHECK(rate>=0), currency char(3) NOT NULL DEFAULT 'CAD', CHECK(NOT(customer_id IS NOT NULL AND customer_group IS NOT NULL)));
CREATE INDEX ix_price_lookup ON price_entries(product_id,unit_code,customer_id);

CREATE TABLE sales_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), customer_id uuid NOT NULL REFERENCES customers(id), public_no text NOT NULL, status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED','PICKING','PARTIALLY_FULFILLED','FULFILLED','CLOSED_WITH_SHORTAGE','CANCELLED')), source_document_id uuid, version integer NOT NULL DEFAULT 1, created_by uuid REFERENCES employees(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,public_no));
CREATE TABLE sales_order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sales_order_id uuid NOT NULL REFERENCES sales_orders(id), product_id uuid NOT NULL REFERENCES products(id), unit_code text NOT NULL, ordered_qty numeric(18,4) NOT NULL CHECK(ordered_qty>=0), dispatched_qty numeric(18,4) NOT NULL DEFAULT 0 CHECK(dispatched_qty>=0), cancelled_qty numeric(18,4) NOT NULL DEFAULT 0 CHECK(cancelled_qty>=0), notes text, CHECK(dispatched_qty+cancelled_qty<=ordered_qty));
CREATE TABLE picking_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sales_order_id uuid NOT NULL REFERENCES sales_orders(id), status text NOT NULL CHECK(status IN('CREATED','IN_PROGRESS','SUBMITTED','VERIFIED','NEEDS_CORRECTION','INVOICED','ABORTED')), verified_by uuid REFERENCES employees(id), verified_at timestamptz, source_document_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE picking_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES picking_attempts(id), order_line_id uuid NOT NULL REFERENCES sales_order_lines(id), picked_qty numeric(18,4) NOT NULL CHECK(picked_qty>=0), unit_code text NOT NULL, shortage_reason text, note text, UNIQUE(attempt_id,order_line_id));

CREATE TABLE invoice_sequences (company_id uuid NOT NULL REFERENCES companies(id), fiscal_year int NOT NULL, last_no bigint NOT NULL CHECK(last_no>=0), PRIMARY KEY(company_id,fiscal_year));
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), sales_order_id uuid REFERENCES sales_orders(id), picking_attempt_id uuid UNIQUE REFERENCES picking_attempts(id), customer_id uuid NOT NULL REFERENCES customers(id), invoice_no text, issued_at timestamptz, due_at timestamptz, state text NOT NULL CHECK(state IN('DRAFT','ISSUED','PARTIALLY_PAID','PAID','VOIDED','CREDITED')), currency char(3) NOT NULL DEFAULT 'CAD', subtotal numeric(18,2) NOT NULL DEFAULT 0, tax_amount numeric(18,2) NOT NULL DEFAULT 0, total numeric(18,2) NOT NULL DEFAULT 0, snapshot jsonb, issued_pdf_sha256 text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,invoice_no));
CREATE TABLE invoice_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), order_line_id uuid REFERENCES sales_order_lines(id), product_id uuid NOT NULL REFERENCES products(id), description_snapshot text NOT NULL, unit_code text NOT NULL, cases numeric(18,4), case_weight_lb numeric(18,4), pieces numeric(18,4), billed_qty numeric(18,4) NOT NULL CHECK(billed_qty>0), unit_rate numeric(18,4) NOT NULL, line_amount numeric(18,2) NOT NULL, pricing_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, lot_id uuid);

CREATE TABLE shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), vendor_id uuid REFERENCES vendors(id), awb_no text, external_invoice_no text, status text NOT NULL CHECK(status IN('DRAFT','DOCUMENTS_REVIEWED','ARRIVED','RECEIVING','RECONCILED','CLOSED','CANCELLED')), currency char(3), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE grns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shipment_id uuid NOT NULL REFERENCES shipments(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), grn_no text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN('DRAFT','NEEDS_REVIEW','COUNTED','APPROVED','POSTED')), approved_by uuid REFERENCES employees(id), posted_at timestamptz);
CREATE TABLE grn_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grn_id uuid NOT NULL REFERENCES grns(id), product_id uuid NOT NULL REFERENCES products(id), declared_qty numeric(18,4), accepted_qty numeric(18,4) NOT NULL CHECK(accepted_qty>=0), damaged_qty numeric(18,4) NOT NULL DEFAULT 0 CHECK(damaged_qty>=0), rejected_qty numeric(18,4) NOT NULL DEFAULT 0 CHECK(rejected_qty>=0), unit_code text NOT NULL, unit_cost numeric(18,4), currency char(3), batch_ref text);

CREATE TABLE inventory_lots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), shipment_id uuid REFERENCES shipments(id), batch_ref text, received_at timestamptz, expires_at timestamptz, status text NOT NULL DEFAULT 'SALEABLE' CHECK(status IN('SALEABLE','DAMAGED','QUARANTINE','EXPIRED')), landed_unit_cost numeric(18,4), cost_currency char(3));
CREATE TABLE inventory_balances (lot_id uuid NOT NULL REFERENCES inventory_lots(id), unit_code text NOT NULL, qty numeric(18,4) NOT NULL DEFAULT 0, reserved_qty numeric(18,4) NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 0, PRIMARY KEY(lot_id,unit_code), CHECK(reserved_qty>=0), CHECK(qty>=0), CHECK(reserved_qty<=qty));
CREATE TABLE stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lot_id uuid NOT NULL REFERENCES inventory_lots(id), product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), unit_code text NOT NULL, delta_qty numeric(18,4) NOT NULL CHECK(delta_qty<>0), movement_type text NOT NULL CHECK(movement_type IN('OPENING_BALANCE','GRN_RECEIPT','INVOICE_DISPATCH','ADJUSTMENT','RETURN','REVERSAL')), source_type text NOT NULL, source_id uuid NOT NULL, source_line_id uuid, posting_key text NOT NULL UNIQUE, reverses_movement_id uuid REFERENCES stock_movements(id), actor_id uuid REFERENCES employees(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_stock_lot_ts ON stock_movements(lot_id,created_at);
CREATE INDEX ix_stock_src ON stock_movements(source_type,source_id);

CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), customer_id uuid REFERENCES customers(id), method text NOT NULL CHECK(method IN('INTERAC','EFT','CHEQUE','CASH','EXTERNAL_CARD')), status text NOT NULL CHECK(status IN('REPORTED','VERIFIED','APPLIED','REJECTED')), amount numeric(18,2) NOT NULL CHECK(amount>0), currency char(3) NOT NULL DEFAULT 'CAD', verification_ref text, verified_by uuid REFERENCES employees(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), invoice_id uuid NOT NULL REFERENCES invoices(id), amount numeric(18,2) NOT NULL CHECK(amount>0), UNIQUE(payment_id,invoice_id));

CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), owner_type text NOT NULL, owner_id uuid NOT NULL, kind text NOT NULL, storage_key text, content_sha256 text, google_drive_file_id text, sync_status text NOT NULL DEFAULT 'PENDING' CHECK(sync_status IN('PENDING','SYNCED','FAILED')), immutable boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scan_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), requested_by uuid NOT NULL REFERENCES employees(id), job_type text NOT NULL, status text NOT NULL, upload_sha256 text, source_document_id uuid REFERENCES documents(id), extraction jsonb, reviewed_by uuid REFERENCES employees(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL, idem_key text NOT NULL, request_hash text NOT NULL, status text NOT NULL, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope,idem_key));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), actor_id uuid REFERENCES employees(id), action text NOT NULL, target_type text, target_id uuid, request_id text, success boolean NOT NULL, detail_redacted jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), event_type text NOT NULL, aggregate_id uuid, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
CREATE TABLE legacy_mappings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), source_system text NOT NULL, entity_kind text NOT NULL, legacy_id text NOT NULL, new_id uuid NOT NULL, import_batch text NOT NULL, UNIQUE(company_id,source_system,entity_kind,legacy_id));
-- IMPORTANT further constraints by triggers/migrations:
-- 1) forbid UPDATE/DELETE on stock_movements and issued invoice snapshots for app role.
-- 2) company-level FK/tenant scoping and document relations validated by application+DB.
-- 3) indexes and currency/tax snapshots, unique GRN posting keys, partial unique active price version.
-- 4) invoice numbering counters locked transactionally and no issuance without approved dispatch.
-- 5) don't assume same stock unit for per-box and lb quantities; model actual measured units.
